/// The standard's read_footprint: every detail of one package, from a .lbr or from a library a
/// board embeds (`library` names it; a .lbr has one). Pads with their number, type, shape,
/// position, size, drill and layers; the layers used; the courtyard box (EAGLE's component
/// exclude layers 39/40, else the pads with the placement outline); graphics per layer; the
/// description; and the 3D packages that instance it.
pub fn read_footprint(xml: &str, library: Option<&str>, name: &str) -> Result<serde_json::Value, LbrError> {
    use serde_json::json;
    let opts = roxmltree::ParsingOptions { allow_dtd: true, ..Default::default() };
    let doc = roxmltree::Document::parse_with_options(xml, opts).map_err(|e| LbrError::NotALibrary(e.to_string()))?;
    let el = |n: &roxmltree::Node, tag: &str| n.is_element() && n.tag_name().name() == tag;
    let layer_names: BTreeMap<String, String> = doc.root_element().descendants().filter(|n| el(n, "layer"))
        .map(|l| (l.attribute("number").unwrap_or("").to_string(), l.attribute("name").unwrap_or("").to_string())).collect();
    let lname = |n: &str| layer_names.get(n).cloned().unwrap_or_else(|| n.to_string());
    let libs: Vec<roxmltree::Node> = doc.root_element().descendants().filter(|n| el(n, "library"))
        .filter(|l| library.map(|want| l.attribute("name").map(|n| n.eq_ignore_ascii_case(want)).unwrap_or(true)).unwrap_or(true)).collect();
    if libs.is_empty() { return Err(LbrError::NotALibrary(format!("no library {}", library.unwrap_or("")))); }
    let pkgs: Vec<roxmltree::Node> = libs.iter().flat_map(|l| l.descendants().filter(|n| el(n, "package") && n.parent().map(|p| el(&p, "packages")).unwrap_or(false)).collect::<Vec<_>>()).collect();
    let Some(pkg) = pkgs.iter().find(|p| p.attribute("name") == Some(name)).or_else(|| pkgs.iter().find(|p| p.attribute("name").map(|n| n.eq_ignore_ascii_case(name)).unwrap_or(false))) else {
        let names: Vec<&str> = pkgs.iter().filter_map(|p| p.attribute("name")).collect();
        return Err(LbrError::NotALibrary(format!("no footprint {name}; the library has {}", names.join(", "))));
    };
    let f = |n: &roxmltree::Node, a: &str| n.attribute(a).and_then(|v| v.parse::<f64>().ok()).unwrap_or(0.0);
    let rot = |n: &roxmltree::Node| n.attribute("rot").unwrap_or("R0").trim_start_matches('S').trim_start_matches('M').trim_start_matches('R').parse::<f64>().unwrap_or(0.0);
    let mut pads = Vec::new();
    let mut used: std::collections::BTreeSet<String> = Default::default();
    let mut graphics: BTreeMap<String, usize> = BTreeMap::new();
    let (mut bx, mut cy) = (Vec::<(f64, f64)>::new(), Vec::<(f64, f64)>::new());
    for g in pkg.children().filter(|c| c.is_element()) {
        match g.tag_name().name() {
            "smd" => {
                let layer = g.attribute("layer").unwrap_or("1");
                let mut layers: Vec<String> = vec![lname(layer)];
                if g.attribute("stop") != Some("no") { layers.push(lname(if layer == "16" { "30" } else { "29" })); }
                if g.attribute("cream") != Some("no") { layers.push(lname(if layer == "16" { "32" } else { "31" })); }
                let (x, y, dx, dy) = (f(&g, "x"), f(&g, "y"), f(&g, "dx"), f(&g, "dy"));
                let rr = f(&g, "roundness");
                bx.extend([(x - dx / 2.0, y - dy / 2.0), (x + dx / 2.0, y + dy / 2.0)]);
                used.extend(layers.iter().cloned());
                pads.push(json!({"number": g.attribute("name").unwrap_or(""), "type": "smd", "shape": if rr >= 100.0 { "round" } else if rr > 0.0 { "roundrect" } else { "rect" },
                                 "at": [x, y], "sizeMm": [dx, dy], "drillMm": null, "layers": layers, "rotation": rot(&g), "roundness": rr}));
            }
            "pad" => {
                let (x, y, d) = (f(&g, "x"), f(&g, "y"), f(&g, "drill"));
                let dia = if f(&g, "diameter") > 0.0 { f(&g, "diameter") } else { d * 1.6 };
                let shape = g.attribute("shape").unwrap_or("round");
                let size = if shape == "long" || shape == "offset" { [dia * 2.0, dia] } else { [dia, dia] };
                bx.extend([(x - size[0] / 2.0, y - size[1] / 2.0), (x + size[0] / 2.0, y + size[1] / 2.0)]);
                let mut layers = vec![lname("1"), lname("16"), lname("17")];
                if g.attribute("stop") != Some("no") { layers.extend([lname("29"), lname("30")]); }
                used.extend(layers.iter().cloned());
                pads.push(json!({"number": g.attribute("name").unwrap_or(""), "type": "thru", "shape": shape, "at": [x, y], "sizeMm": size, "drillMm": d,
                                 "layers": layers, "rotation": rot(&g), "plated": true}));
            }
            "hole" => {
                let (x, y, d) = (f(&g, "x"), f(&g, "y"), f(&g, "drill"));
                used.insert(lname("45"));
                pads.push(json!({"number": "", "type": "npth", "shape": "round", "at": [x, y], "sizeMm": [d, d], "drillMm": d, "layers": [lname("45")], "rotation": 0.0, "plated": false}));
            }
            "description" => {}
            tag => {
                if let Some(l) = g.attribute("layer") {
                    *graphics.entry(lname(l)).or_default() += 1;
                    used.insert(lname(l));
                    let mut pts: Vec<(f64, f64)> = match tag {
                        "wire" | "rectangle" => vec![(f(&g, "x1"), f(&g, "y1")), (f(&g, "x2"), f(&g, "y2"))],
                        "circle" => { let (x, y, r) = (f(&g, "x"), f(&g, "y"), f(&g, "radius")); vec![(x - r, y - r), (x + r, y + r)] }
                        _ => g.descendants().filter(|v| el(v, "vertex")).map(|v| (f(&v, "x"), f(&v, "y"))).collect(),
                    };
                    if l == "39" || l == "40" { cy.append(&mut pts); } else if l == "21" || l == "22" || l == "51" || l == "52" { bx.append(&mut pts); }
                }
            }
        }
    }
    let boxed = |p: &[(f64, f64)]| -> serde_json::Value {
        if p.is_empty() { return serde_json::Value::Null; }
        let r = |v: f64| (v * 10000.0).round() / 10000.0;
        json!([r(p.iter().map(|q| q.0).fold(f64::MAX, f64::min)), r(p.iter().map(|q| q.1).fold(f64::MAX, f64::min)),
               r(p.iter().map(|q| q.0).fold(f64::MIN, f64::max)), r(p.iter().map(|q| q.1).fold(f64::MIN, f64::max))])
    };
    let (courtyard, measured) = if !cy.is_empty() { (boxed(&cy), "component exclude layer (39/40)") } else { (boxed(&bx), "pads and placement outline (the package has no exclude layer)") };
    let lib_name = pkg.ancestors().find(|a| el(a, "library")).and_then(|l| l.attribute("name")).unwrap_or("");
    let models: Vec<serde_json::Value> = libs.iter().flat_map(|l| l.descendants().filter(|n| el(n, "package3d")).collect::<Vec<_>>())
        .filter(|p3| p3.descendants().any(|i| el(&i, "packageinstance") && i.attribute("name") == pkg.attribute("name")))
        .map(|p3| json!({"name": p3.attribute("name").unwrap_or(""), "urn": p3.attribute("urn").filter(|u| !u.is_empty()).or(p3.attribute("wip_urn")).unwrap_or(""),
                         "type": p3.attribute("type").unwrap_or(""), "path": null, "offset": null, "scale": null, "rotate": null})).collect();
    let smd = pads.iter().filter(|p| p["type"] == "smd").count();
    let tht = pads.iter().filter(|p| p["type"] == "thru").count();
    Ok(json!({
        "name": pkg.attribute("name").unwrap_or(""), "library": lib_name,
        "description": pkg.children().find(|c| el(c, "description")).and_then(|d| d.text()).unwrap_or("").trim(),
        "pads": pads, "layers": used.into_iter().collect::<Vec<_>>(), "courtyardMm": courtyard, "courtyardFrom": measured, "graphics": graphics,
        "attributes": {"mount": if tht > 0 && smd > 0 { "mixed" } else if tht > 0 { "tht" } else if smd > 0 { "smd" } else { "none" }, "excludeFromBom": null, "excludeFromPos": null, "dnp": null},
        "properties": {"locallyModified": pkg.attribute("locally_modified").unwrap_or("no")},
        "models": models,
    }))
}

/// The standard's edit_footprint on one package of a .lbr (or a board-embedded library's text):
/// pads changed, deleted, added or renumbered (a device's connects follow a renamed pad, and a
/// deleted pad's connects are dropped and reported); graphics appended to, replaced on or deleted
/// from a layer; the description set. 3D models are Fusion cloud links (package3d URNs), so a
/// models edit is refused. Returns the new document text and what changed.
pub fn edit_footprint(xml: &str, name: &str, edits: &serde_json::Value) -> Result<(String, serde_json::Value), String> {
    use serde_json::{json, Value};
    let mut root = Element::parse(xml).map_err(|e| e.to_string())?;
    let layer_names: Vec<(String, String)> = {
        let mut v = Vec::new();
        fn walk(e: &Element, v: &mut Vec<(String, String)>) { if e.tag == "layer" { v.push((e.attr("number").unwrap_or("").into(), e.attr("name").unwrap_or("").into())); } for c in &e.children { walk(c, v); } }
        walk(&root, &mut v); v
    };
    let layer_of = |l: &Value| -> Result<String, String> {
        if let Some(n) = l.as_u64() { return Ok(n.to_string()); }
        let s = l.as_str().unwrap_or("");
        let std_ = [("F.Cu", "1"), ("B.Cu", "16"), ("F.SilkS", "21"), ("B.SilkS", "22"), ("F.Fab", "51"), ("B.Fab", "52"), ("F.CrtYd", "39"), ("B.CrtYd", "40"),
                    ("F.Mask", "29"), ("B.Mask", "30"), ("F.Paste", "31"), ("B.Paste", "32"), ("Edge.Cuts", "20"), ("Dwgs.User", "48"), ("Cmts.User", "48")];
        if let Some((_, n)) = std_.iter().find(|(k, _)| k.eq_ignore_ascii_case(s)) { return Ok(n.to_string()); }
        if s.chars().all(|c| c.is_ascii_digit()) && !s.is_empty() { return Ok(s.to_string()); }
        layer_names.iter().find(|(_, nm)| nm.eq_ignore_ascii_case(s)).map(|(n, _)| n.clone()).ok_or_else(|| format!("unknown layer {s}"))
    };
    if !edits["models"].is_null() { return Err("models: Fusion links a package to its 3D model by cloud URN (package3d); edit it in Fusion's 3D package editor (fusion_show_3d_package)".into()); }
    let f = |v: f64| { let s = format!("{:.4}", v); s.trim_end_matches('0').trim_end_matches('.').to_string() };
    let mut changed: Vec<Value> = Vec::new();
    let mut renames: Vec<(String, String)> = Vec::new();
    let mut deleted: Vec<String> = Vec::new();
    {
        let lib = root.find_deep_mut("library").ok_or("no <library>")?;
        let pkgs = lib.find_child_mut("packages").ok_or("no <packages>")?;
        let pkg = pkgs.children.iter_mut().find(|p| p.tag == "package" && p.attr("name") == Some(name)).ok_or_else(|| format!("no footprint {name}"))?;
        let set_attr = |e: &mut Element, k: &str, v: String| { match e.attrs.iter_mut().find(|(kk, _)| kk == k) { Some(a) => a.1 = v, None => e.attrs.push((k.into(), v)) } };
        let is_pad = |e: &Element| e.tag == "smd" || e.tag == "pad";
        let make_pad = |spec: &Value, number: &str| -> Result<Element, String> {
            let thru = matches!(spec["type"].as_str(), Some("thru") | Some("tht") | Some("pad"));
            let mut e = Element::new(if thru { "pad" } else { "smd" });
            let at = spec["at"].as_array().ok_or("a new pad needs at [x, y]")?;
            e.attrs = vec![("name".into(), number.into()), ("x".into(), f(at[0].as_f64().unwrap_or(0.0))), ("y".into(), f(at[1].as_f64().unwrap_or(0.0)))];
            let size = spec["sizeMm"].as_array();
            if thru {
                let d = spec["drillMm"].as_f64().ok_or("a through pad needs drillMm")?;
                e.attrs.push(("drill".into(), f(d)));
                if let Some(s) = size { e.attrs.push(("diameter".into(), f(s[0].as_f64().unwrap_or(0.0)))); }
                if let Some(sh) = spec["shape"].as_str() { e.attrs.push(("shape".into(), match sh { "rect" | "square" => "square", "oval" | "long" => "long", "octagon" => "octagon", _ => "round" }.into())); }
            } else {
                let s = size.ok_or("an SMD pad needs sizeMm [w, h]")?;
                e.attrs.push(("dx".into(), f(s[0].as_f64().unwrap_or(0.0)))); e.attrs.push(("dy".into(), f(s[1].as_f64().unwrap_or(0.0))));
                let layer = spec["layers"].as_array().and_then(|l| l.first()).map(|l| if l.as_str().map(|s| s.starts_with("B.")).unwrap_or(false) { "16" } else { "1" }).unwrap_or("1");
                e.attrs.push(("layer".into(), layer.into()));
                if let Some(sh) = spec["shape"].as_str() { if sh != "rect" { e.attrs.push(("roundness".into(), if sh == "roundrect" { "25" } else { "100" }.into())); } }
            }
            if let Some(r) = spec["rotation"].as_f64() { if r != 0.0 { e.attrs.push(("rot".into(), format!("R{}", f(r)))); } }
            Ok(e)
        };
        // pad edits
        for pe in edits["pads"].as_array().cloned().unwrap_or_default() {
            let num = pe["number"].as_str().map(str::to_string).or(pe["number"].as_u64().map(|n| n.to_string())).ok_or("each pad edit needs number")?;
            let idx = pkg.children.iter().position(|c| is_pad(c) && c.attr("name") == Some(num.as_str())).ok_or_else(|| format!("no pad {num} in {name}"))?;
            if pe["delete"].as_bool() == Some(true) { pkg.children.remove(idx); deleted.push(num.clone()); changed.push(json!({"pad": num, "what": "deleted"})); continue; }
            let set = &pe["set"];
            if let Some(t) = set["type"].as_str() {
                let want_thru = matches!(t, "thru" | "tht" | "pad");
                if want_thru != (pkg.children[idx].tag == "pad") {
                    let old = &pkg.children[idx];
                    let mut spec = set.clone();
                    if spec["at"].is_null() { spec["at"] = json!([old.attr("x").and_then(|v| v.parse::<f64>().ok()).unwrap_or(0.0), old.attr("y").and_then(|v| v.parse::<f64>().ok()).unwrap_or(0.0)]); }
                    let e = make_pad(&spec, &num)?;
                    pkg.children[idx] = Element { tail: pkg.children[idx].tail.clone(), ..e };
                    changed.push(json!({"pad": num, "what": format!("type {t}")}));
                }
            }
            let e = &mut pkg.children[idx];
            if let Some(at) = set["at"].as_array() { set_attr(e, "x", f(at[0].as_f64().unwrap_or(0.0))); set_attr(e, "y", f(at[1].as_f64().unwrap_or(0.0))); changed.push(json!({"pad": num, "what": "at"})); }
            if let Some(s) = set["sizeMm"].as_array() {
                if e.tag == "smd" { set_attr(e, "dx", f(s[0].as_f64().unwrap_or(0.0))); set_attr(e, "dy", f(s[1].as_f64().unwrap_or(0.0))); } else { set_attr(e, "diameter", f(s[0].as_f64().unwrap_or(0.0))); }
                changed.push(json!({"pad": num, "what": "size"}));
            }
            if let Some(d) = set["drillMm"].as_f64() { if e.tag != "pad" { return Err(format!("pad {num} is SMD: drillMm needs type thru")); } set_attr(e, "drill", f(d)); changed.push(json!({"pad": num, "what": "drill"})); }
            if let Some(r) = set["rotation"].as_f64() { set_attr(e, "rot", format!("R{}", f(r))); changed.push(json!({"pad": num, "what": "rotation"})); }
            if let Some(sh) = set["shape"].as_str() {
                if e.tag == "smd" { set_attr(e, "roundness", match sh { "rect" => "0", "roundrect" => "25", _ => "100" }.into()); }
                else { set_attr(e, "shape", match sh { "rect" | "square" => "square", "oval" | "long" => "long", "octagon" => "octagon", _ => "round" }.into()); }
                changed.push(json!({"pad": num, "what": "shape"}));
            }
            if let Some(ls) = set["layers"].as_array() { if e.tag == "smd" { let l = if ls.iter().any(|l| l.as_str().map(|s| s.starts_with("B.")).unwrap_or(false)) { "16" } else { "1" }; set_attr(e, "layer", l.into()); changed.push(json!({"pad": num, "what": "layer"})); } }
            if let Some(nn) = set["newNumber"].as_str().map(str::to_string).or(set["newNumber"].as_u64().map(|n| n.to_string())) { set_attr(e, "name", nn.clone()); renames.push((num.clone(), nn.clone())); changed.push(json!({"pad": num, "what": format!("renumbered {nn}")})); }
        }
        // new pads
        for spec in edits["addPads"].as_array().cloned().unwrap_or_default() {
            let num = spec["number"].as_str().map(str::to_string).or(spec["number"].as_u64().map(|n| n.to_string())).ok_or("a new pad needs number")?;
            if pkg.children.iter().any(|c| is_pad(c) && c.attr("name") == Some(num.as_str())) { return Err(format!("pad {num} already exists in {name}")); }
            let e = make_pad(&spec, &num)?;
            let at = pkg.children.iter().rposition(|c| is_pad(c)).map(|i| i + 1).unwrap_or(pkg.children.len());
            pkg.children.insert(at, e);
            changed.push(json!({"pad": num, "what": "added"}));
        }
        // renumbering
        let rn = &edits["renumber"];
        let mut map: Vec<(String, String)> = Vec::new();
        if let Some(m) = rn["map"].as_object() { map = m.iter().map(|(k, v)| (k.clone(), v.as_str().map(str::to_string).unwrap_or(v.to_string()))).collect(); }
        else if rn["sequential"].as_bool() == Some(true) {
            let start = rn["start"].as_u64().unwrap_or(1);
            map = pkg.children.iter().filter(|c| is_pad(c)).enumerate().map(|(i, c)| (c.attr("name").unwrap_or("").to_string(), (start + i as u64).to_string())).collect();
        }
        if !map.is_empty() {
            let olds: Vec<String> = pkg.children.iter().filter(|c| is_pad(c)).map(|c| c.attr("name").unwrap_or("").to_string()).collect();
            for (from, _) in &map { if !olds.contains(from) { return Err(format!("renumber: no pad {from}")); } }
            let finals: Vec<String> = olds.iter().map(|o| map.iter().find(|(f_, _)| f_ == o).map(|(_, t)| t.clone()).unwrap_or(o.clone())).collect();
            let mut seen = std::collections::HashSet::new();
            if let Some(d) = finals.iter().find(|n| !seen.insert(n.as_str())) { return Err(format!("renumber gives two pads the number {d}")); }
            for c in pkg.children.iter_mut().filter(|c| is_pad(c)) {
                let old = c.attr("name").unwrap_or("").to_string();
                if let Some((_, to)) = map.iter().find(|(f_, _)| *f_ == old) { if *to != old { set_attr(c, "name", to.clone()); renames.push((old, to.clone())); } }
            }
            changed.push(json!({"what": format!("renumbered {} pads", map.len())}));
        }
        // graphics
        for g in edits["graphics"].as_array().cloned().unwrap_or_default() {
            let layer = layer_of(&g["layer"])?;
            let mode = g["mode"].as_str().unwrap_or("append");
            if mode == "replace" || mode == "delete" {
                let before = pkg.children.len();
                pkg.children.retain(|c| is_pad(c) || c.tag == "description" || c.tag == "hole" || c.attr("layer") != Some(layer.as_str()));
                changed.push(json!({"layer": layer, "what": format!("{} graphics removed", before - pkg.children.len())}));
                if mode == "delete" { continue; }
            }
            let w = f(g["widthMm"].as_f64().unwrap_or(0.12));
            let mut n = 0;
            for s in g["shapes"].as_array().cloned().unwrap_or_default() {
                let pt = |v: &Value| -> (String, String) { (f(v[0].as_f64().unwrap_or(0.0)), f(v[1].as_f64().unwrap_or(0.0))) };
                let mut e: Element;
                match s["type"].as_str().unwrap_or("") {
                    "line" | "arc" => {
                        let (a, b) = (pt(&s["start"]), pt(&s["end"]));
                        e = Element::new("wire");
                        e.attrs = vec![("x1".into(), a.0), ("y1".into(), a.1), ("x2".into(), b.0), ("y2".into(), b.1), ("width".into(), w.clone()), ("layer".into(), layer.clone())];
                        if let Some(c) = s["angle"].as_f64() { e.attrs.push(("curve".into(), f(c))); }
                    }
                    "rect" => {
                        let (a, b) = (pt(&s["start"]), pt(&s["end"]));
                        e = Element::new("rectangle");
                        e.attrs = vec![("x1".into(), a.0), ("y1".into(), a.1), ("x2".into(), b.0), ("y2".into(), b.1), ("layer".into(), layer.clone())];
                    }
                    "circle" => {
                        let c = pt(&s["center"]);
                        e = Element::new("circle");
                        e.attrs = vec![("x".into(), c.0), ("y".into(), c.1), ("radius".into(), f(s["radius"].as_f64().unwrap_or(0.5))), ("width".into(), w.clone()), ("layer".into(), layer.clone())];
                    }
                    "poly" => {
                        e = Element::new("polygon");
                        e.attrs = vec![("width".into(), w.clone()), ("layer".into(), layer.clone())];
                        for p in s["points"].as_array().cloned().unwrap_or_default() { let q = pt(&p); let mut v = Element::new("vertex"); v.attrs = vec![("x".into(), q.0), ("y".into(), q.1)]; e.children.push(v); }
                        if e.children.len() < 3 { return Err("a poly needs three points".into()); }
                    }
                    other => return Err(format!("unknown shape type {other}")),
                }
                pkg.children.push(e); n += 1;
            }
            if n > 0 { changed.push(json!({"layer": layer, "what": format!("{n} graphics added")})); }
        }
        // metadata
        if let Some(d) = edits["metadata"]["description"].as_str() {
            match pkg.children.iter_mut().find(|c| c.tag == "description") { Some(e) => e.text = d.to_string(), None => { let mut e = Element::new("description"); e.text = d.to_string(); pkg.children.insert(0, e); } }
            changed.push(json!({"what": "description"}));
        }
        set_attr(pkg, "locally_modified", "yes".into());
    }
    // devices that use the package follow renamed and deleted pads
    let mut dropped: Vec<Value> = Vec::new();
    fn fix(e: &mut Element, name: &str, renames: &[(String, String)], deleted: &[String], dropped: &mut Vec<Value>) {
        if e.tag == "device" && e.attr("package") == Some(name) {
            if let Some(cs) = e.find_child_mut("connects") {
                cs.children.retain(|c| { let keep = !deleted.iter().any(|d| c.attr("pad").map(|p| p.split(' ').any(|q| q == d)).unwrap_or(false)); if !keep { dropped.push(serde_json::json!({"pin": c.attr("pin"), "pad": c.attr("pad")})); } keep });
                for c in cs.children.iter_mut() {
                    if let Some(pad) = c.attr("pad").map(str::to_string) {
                        let np: Vec<String> = pad.split(' ').map(|q| renames.iter().find(|(f_, _)| f_ == q).map(|(_, t)| t.clone()).unwrap_or(q.to_string())).collect();
                        let v = np.join(" ");
                        if v != pad { if let Some(a) = c.attrs.iter_mut().find(|(k, _)| k == "pad") { a.1 = v; } }
                    }
                }
            }
        }
        for c in e.children.iter_mut() { fix(c, name, renames, deleted, dropped); }
    }
    fix(&mut root, name, &renames, &deleted, &mut dropped);
    let text = root.to_xml_document();
    Ok((text, json!({"changed": changed, "connectsDropped": dropped, "renamed": renames.iter().map(|(a, b)| json!({"from": a, "to": b})).collect::<Vec<_>>()})))
}
